"use client"

import * as React from "react"

import { Button } from "@/components/ui/button"
import { Field, FieldDescription, FieldError, FieldLabel } from "@/components/ui/field"
import { Input } from "@/components/ui/input"

type Newsletter01Status = "idle" | "invalid" | "sending" | "failed" | "done"

type Newsletter01FormProps = {
  status: Newsletter01Status
  email: string
  onEmailChange: (email: string) => void
  onSubmit: () => void
  onReset: () => void
}

function Newsletter01Form({ status, email, onEmailChange, onSubmit, onReset }: Newsletter01FormProps) {
  const id = React.useId()
  const inputRef = React.useRef<HTMLInputElement>(null)
  const doneRef = React.useRef<HTMLDivElement>(null)
  const bad = status === "invalid" || status === "failed"

  React.useEffect(() => {
    if (status === "done") doneRef.current?.focus()
    if (status === "invalid" || status === "failed") inputRef.current?.focus()
  }, [status])

  if (status === "done") {
    return (
      <div ref={doneRef} tabIndex={-1} role="status" className="rounded-none outline-none">
        <p className="font-script text-3xl leading-none font-bold text-ink">You&rsquo;re on the list.</p>
        <p className="mt-2 text-lg/7 text-ink-soft">
          We sent a note to <strong className="font-bold text-ink">{email}</strong>. Click the link inside to confirm, and the first letter lands on Sunday.
        </p>
        <Button type="button" variant="link" size="sm" onClick={onReset} className="-ms-3 mt-1">
          Use a different address
        </Button>
      </div>
    )
  }

  return (
    <form
      noValidate
      onSubmit={(e) => {
        e.preventDefault()
        onSubmit()
      }}
    >
      <Field data-invalid={bad || undefined}>
        <FieldLabel htmlFor={`${id}-email`}>Your email address</FieldLabel>
        <div className="flex flex-col gap-3 @lg:flex-row @lg:gap-4">
          <Input
            ref={inputRef}
            id={`${id}-email`}
            type="email"
            name="email"
            autoComplete="email"
            required
            placeholder="you@example.com"
            value={email}
            onChange={(e) => onEmailChange(e.target.value)}
            aria-invalid={bad || undefined}
            aria-describedby={`${id}-help${bad ? ` ${id}-error` : ""}`}
            className="min-w-0 @lg:flex-1"
          />
          <Button type="submit" disabled={status === "sending"}>
            {status === "sending" ? "Subscribing…" : "Subscribe"}
          </Button>
        </div>
        <FieldDescription id={`${id}-help`}>No spam. Leave with one click. 12,400 people read it.</FieldDescription>
        {status === "invalid" ? <FieldError id={`${id}-error`}>That does not look like an email address. Check it for typos?</FieldError> : null}
        {status === "failed" ? <FieldError id={`${id}-error`}>Something went wrong on our side. Please try again in a moment.</FieldError> : null}
      </Field>
    </form>
  )
}

export { Newsletter01Form }
export type { Newsletter01Status }

"use client"

import * as React from "react"

import { Lettering } from "@/components/ui/lettering"
import { Paper } from "@/components/ui/paper"
import { Newsletter01Envelope } from "@/components/blocks/newsletter-01/components/newsletter-01-envelope"
import { Newsletter01Form, type Newsletter01Status } from "@/components/blocks/newsletter-01/components/newsletter-01-form"

type Newsletter01Props = {
  onSubscribe?: (email: string) => void | Promise<void>
}

const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/

export default function Newsletter01({ onSubscribe }: Newsletter01Props) {
  const titleId = React.useId()
  const [status, setStatus] = React.useState<Newsletter01Status>("idle")
  const [email, setEmail] = React.useState("")
  const [open, setOpen] = React.useState(false)

  const submit = async () => {
    if (!EMAIL.test(email.trim())) {
      setStatus("invalid")
      return
    }
    setStatus("sending")
    try {
      await onSubscribe?.(email.trim())
      setStatus("done")
      setOpen(true)
    } catch {
      setStatus("failed")
    }
  }

  return (
    <section aria-labelledby={titleId} className="@container relative w-full overflow-x-clip">
      <div className="px-8 py-14 @xl:py-20">
        <div className="mx-auto grid max-w-5xl items-center gap-x-14 gap-y-6 @3xl:grid-cols-[minmax(0,1.1fr)_minmax(0,1fr)]">
          <Paper stock="paper" tilt={false} tape="corner" tapeKind="washi-dots" seed="newsletter-card" className="px-6 py-8 @xl:px-9 @xl:py-10">
            <p className="font-type text-sm text-pencil-text">The Sunday letter</p>
            <Lettering as="h2" id={titleId} size="md" tone="marker" wobble={0.4} seed="newsletter-title" className="mt-3">
              One short letter, every Sunday
            </Lettering>
            <p className="mt-4 mb-6 text-lg/7 text-ink-soft">What we shipped, what we drew, and one good link. Three minutes, best with tea.</p>
            <Newsletter01Form
              status={status}
              email={email}
              onEmailChange={(v) => {
                setEmail(v)
                if (status === "invalid" || status === "failed") setStatus("idle")
              }}
              onSubmit={submit}
              onReset={() => {
                setStatus("idle")
                setEmail("")
                setOpen(false)
              }}
            />
          </Paper>

          <Newsletter01Envelope open={open} onOpenChange={setOpen} stamped={status === "done"} />
        </div>
      </div>
    </section>
  )
}

export type { Newsletter01Props }
